  perform journal_note(p_world, p_uid, 'swirl');
  perform skill_raise(p_world, p_uid, elementalism_skill(), 1);
  perform tell(p_world, p_uid, 'Collected: ' || motes_word(v_n, s.element) || '. Swirl gone.', 'event');
